const updateConfigSettings = `-- name: UpdateConfigSettings :one
UPDATE device_integration_configs
SET settings = $1,
    enabled = $2,
    updated_at = clock_timestamp()
WHERE organization_id = $3
  AND provider = $4
  AND deleted IS FALSE
RETURNING id, organization_id, provider, credentials_encrypted, settings, enabled, created_at, updated_at, deleted_at, deleted
`

type UpdateConfigSettingsParams struct {
	Settings       []byte
	Enabled        bool
	OrganizationID string
	Provider       string
}

func (q *Queries) UpdateConfigSettings(ctx context.Context, arg UpdateConfigSettingsParams) (DeviceIntegrationConfig, error) {
	row := q.db.QueryRow(ctx, updateConfigSettings,
		arg.Settings,
		arg.Enabled,
		arg.OrganizationID,
		arg.Provider,
	)
	var i DeviceIntegrationConfig
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.Provider,
		&i.CredentialsEncrypted,
		&i.Settings,
		&i.Enabled,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.Deleted,
	)
	return i, err
}
